const client = $input.first().json;
const sheetUrl = `https://docs.google.com/spreadsheets/d/${client.sheet_id}/gviz/tq?tqx=out:json&sheet=CRM`;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: sheetUrl,
    returnFullResponse: true
  });

  let raw = response.body;
  if (typeof raw === 'string') {
    raw = raw.replace(/^\/\*O_o\*\/\n/, '').replace(/^google\.visualization\.Query\.setResponse\(/, '').replace(/\);?\s*$/, '');
  }
  const data = JSON.parse(raw);
  const rows = data.table?.rows || [];

  const parsedRows = rows.map(row => {
    const c = row.c || [];
    return {
      data: c[0]?.v || null,
      hora: c[1]?.v || null,
      nome: c[2]?.v || null,
      numero: c[3]?.v || null,
      mensagem: c[4]?.v || null,
      status: c[5]?.v || null,
      origem: c[6]?.v || null,
      suborigem: c[7]?.v || null,
      mes: c[8]?.v || null,
      contato: c[9]?.v || null,
      agendou: c[10]?.v || null,
      data_agendamento: c[11]?.v || null,
      compareceu: c[12]?.v || null,
      ganhou: c[13]?.v || null,
      motivo_perda: c[14]?.v || null,
      receita_consultas: c[15]?.v || null,
      receita_tratamentos: c[16]?.v || null,
      observacoes: c[17]?.v || null,
      campanha: c[18]?.v || null,
      conjunto: c[19]?.v || null,
      anuncio: c[20]?.v || null,
      criativo: c[21]?.v || null,
      source_id: c[22]?.v || null,
      plataforma: c[23]?.v || null,
      instancia: c[24]?.v || null,
      filtros: c[25]?.v || null,
      data_agendado: c[26]?.v || null,
      data_compareceu: c[27]?.v || null,
      data_ganho: c[28]?.v || null,
      data_perdido: c[29]?.v || null,
      data_contato: c[30]?.v || null
    };
  });

  return [{ json: { ...client, rows: parsedRows, total_rows: parsedRows.length } }];
} catch (e) {
  return [{ json: { ...client, rows: [], total_rows: 0, error: e.message } }];
}

const client = $input.first().json;
const rows = client.rows || [];
const now = new Date();
const currentMonth = now.toLocaleString('pt-BR', { month: 'long' }).toLowerCase();

const monthRows = rows.filter(r => {
  if (!r.mes) return false;
  const mesLower = r.mes.toLowerCase().trim();
  return mesLower.includes(currentMonth) || mesLower.includes(String(now.getMonth() + 1).padStart(2, '0'));
});

const totalLeads = monthRows.length;
const contatoFeito = monthRows.filter(r => r.contato && r.contato.toLowerCase().includes('contato feito')).length;
const agendados = monthRows.filter(r => r.agendou && r.agendou.trim() !== '').length;
const compareceram = monthRows.filter(r => r.compareceu && r.compareceu.trim() !== '').length;
const fechados = monthRows.filter(r => r.ganhou && r.ganhou.trim() !== '').length;
const perdidos = monthRows.filter(r => r.data_perdido && r.data_perdido.trim() !== '').length;

const pct = (v, t) => t > 0 ? Math.round((v / t) * 100) : 0;

let totalRespTime = 0;
let respCount = 0;
for (const r of monthRows) {
  if (r.data && r.data_contato) {
    try {
      const entrada = new Date(r.data);
      const contato = new Date(r.data_contato);
      if (!isNaN(entrada) && !isNaN(contato)) {
        totalRespTime += (contato - entrada) / 3600000;
        respCount++;
      }
    } catch (e) {}
  }
}

const status = (() => {
  const taxaAgend = pct(agendados, totalLeads);
  const taxaComp = pct(compareceram, agendados);
  const taxaVenda = pct(fechados, compareceram);
  if (taxaAgend >= 40 && taxaComp >= 70 && taxaVenda >= 50 && perdidos === 0) return 'saudavel';
  if (taxaAgend < 25 || taxaComp < 50 || taxaVenda < 30 || perdidos >= 3) return 'gargalo';
  return 'atencao';
})();

return [{ json: {
  id: client.id, name: client.name, seg: client.seg,
  leads: totalLeads, contato: contatoFeito,
  agendados, compareceram, fechados, perdidos,
  pct_agend: pct(agendados, totalLeads),
  pct_comp: pct(compareceram, agendados),
  pct_venda: pct(fechados, compareceram),
  resp_h: respCount > 0 ? Math.round((totalRespTime / respCount) * 10) / 10 : 0,
  status,
  _debug: { total_rows: rows.length, month_rows: monthRows.length, current_month: currentMonth }
}}];

const items = $input.all();
const clients = items.map(i => i.json);
return [{ json: { clients, generated_at: new Date().toISOString(), period: { from: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0], to: new Date().toISOString().split('T')[0] } } }];
